-- 목적: book_text 페이지 단위 본문 적재 (asb · 이 파일: 7of11)
-- 실행자: 팀장(Supabase SQL Editor). 워커 초안. 워커 DB 직접 쓰기 금지.
-- 근거 ADR: ADR-0056 (ADR-0056 D1·D2·D4·D5) · Accepted 2026-08-10
-- source 라벨: manifest_txt_v1
-- 이 파일 담당: 48권 / 438행 (정제 후 빈 면 0행 포함 — D7)
-- 생성기: scripts/tts_pilot/gen_book_text_sql_v2.py
-- 매핑: page_index = (P번호|json page) - 1 (0-based, D2/D11). blocks = NULL(원천에 블록 정보 없음).
-- 정제: tts_targets.sanitize() 공유(D6). 표지 행 없음(D3).
-- 인용: $$ 달러 인용. 생성 시 '$$' 포함·'$' 종결 전수 가드 통과.
-- 중복: ON CONFLICT (book_id, page_index) DO NOTHING — 기존 행을 덮어쓰지 않는다.
--
-- ★ 이 파일은 ROLLBACK; 으로 끝난다. [적재검증]까지 기대값과 일치하면
--   마지막 ROLLBACK; 을 COMMIT; 으로 직접 바꿔 타이핑해 확정한다.

-- ───────── [선검증] 트랜잭션 밖 ─────────
-- (a) 대상 권의 기존 book_text 행 수 — 기대 0. 0이 아니면 중단하고 보고할 것.
SELECT count(*) AS rows_before FROM book_text bt
  JOIN books b ON b.id = bt.book_id
  WHERE b.source_platform='african_storybook' AND b.source_id IN ('33035', '33042', '33047', '33082', '33142', '33145', '33215', '33600', '33679', '33684', '33732', '33738', '33761', '33926', '33968', '34005', '34094', '34098', '34111', '34242', '34274', '34285', '34359', '34414', '34418', '34450', '34544', '34547', '34548', '34549', '34575', '34577', '34656', '34668', '35033', '35250', '35252', '35302', '35347', '35350', '35356', '35392', '35415', '35417', '35419', '35421', '35428', '35430');
-- (b) 대상 source_id 중 books에 존재하는 권 수 — 기대 48
SELECT count(*) AS books_found FROM books
  WHERE source_platform='african_storybook' AND source_id IN ('33035', '33042', '33047', '33082', '33142', '33145', '33215', '33600', '33679', '33684', '33732', '33738', '33761', '33926', '33968', '34005', '34094', '34098', '34111', '34242', '34274', '34285', '34359', '34414', '34418', '34450', '34544', '34547', '34548', '34549', '34575', '34577', '34656', '34668', '35033', '35250', '35252', '35302', '35347', '35350', '35356', '35392', '35415', '35417', '35419', '35421', '35428', '35430');

-- ───────── [적재] ─────────
BEGIN;
INSERT INTO book_text (book_id, page_index, text, blocks, source)
SELECT b.id, v.page_index, v.text, NULL::jsonb, $$manifest_txt_v1$$
  FROM (VALUES
