    ('34005', 0, $$There once lived a little cat.$$),
    ('34005', 1, $$And there was a little mouse$$),
    ('34005', 2, $$One day Mr. mouse said to Mr. Cat , let us do something nice for Mr.dog. He provides us shelter for free.$$),
